private boolean gameOver() {
    int i = 0;
    for (int frame = 0; frame < FRAMES; frame++) {
        if (i >= rolls.size()) {
            return false;
        }
        if (frame < FRAMES - 1) {
            if (rolls.get(i) == PINS) {
                i += 1;
            } else {
                i += 2;
