        } else {
            // 10th frame
            if (i + 1 >= rolls.size()) {
                return false;
            }
            int first = rolls.get(i);
            int second = rolls.get(i + 1);
            if (first == PINS || first + second == PINS) {
                return i + 3 <= rolls.size();
            }
            return i + 2 <= rolls.size();
        }
    }
    return true;
}
