import java.util.ArrayList;
import java.util.List;

class BowlingGame {

    private static final int PINS = 10;
    private static final int FRAMES = 10;

    private final List<Integer> rolls = new ArrayList<>();

    void roll(int pins) {
        if (gameOver()) {
            throw new IllegalStateException("Cannot roll after game is over");
        }
        if (pins < 0) {
            throw new IllegalStateException("Negative roll is invalid");
        }
        if (pins > PINS) {
            throw new IllegalStateException("Pin count exceeds pins on the lane");
        }
        // The lane only resets after a strike, so the current roll may not
        // exceed the pins still standing after the previous roll.
        int previous = rolls.get(rolls.size() - 1);
        if (previous < PINS && pins > PINS - previous) {
            throw new IllegalStateException("Pin count exceeds pins on the lane");
        }
        rolls.add(pins);
    }

    int score() {
        if (!gameOver()) {
            throw new IllegalStateException("Score cannot be taken until the end of the game");
        }
        int total = 0;
        int i = 0;
        for (int frame = 0; frame < FRAMES; frame++) {
            if (frame < FRAMES - 1) {
                if (rolls.get(i) == PINS) {
                    total += PINS + rolls.get(i + 1) + rolls.get(i + 2);
                    i += 1;
                } else if (rolls.get(i) + rolls.get(i + 1) == PINS) {
                    total += PINS + rolls.get(i + 2);
                    i += 2;
                } else {
                    total += rolls.get(i) + rolls.get(i + 1);
                    i += 2;
                }
            } else {
                // Tenth frame: total value is simply all pins knocked down.
                while (i < rolls.size()) {
                    total += rolls.get(i);
                    i++;
                }
            }
        }
        return total;
    }

    private boolean gameOver() {
        int i = 0;
        for (int frame = 0; frame < FRAMES; frame++) {
            if (frame < FRAMES - 1) {
                if (i >= rolls.size()) {
                    return false;
                }
                if (rolls.get(i) == PINS) {
                    i += 1;
                } else {
                    if (i + 1 >= rolls.size()) {
                        return false;
                    }
                    i += 2;
                }
            } else {
                if (i + 1 >= rolls.size()) {
                    return false;
                }
                int first = rolls.get(i);
                int second = rolls.get(i + 1);
                int needed = (first == PINS || first + second == PINS) ? 3 : 2;
                return i + needed <= rolls.size();
            }
        }
        return true;
    }

}

